import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { AvatarComponent } from '../avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { CommonModule } from '@angular/common';
import { IconComponent } from '../icon/icon.component';
import { FormsModule } from '@angular/forms';
import { IndividualService } from '../../../userpanel/services/individual/individual.service';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { RolepermitService } from '../../../core/services/permission/rolepermit.service';
import { NavSharePermissionComponent } from '../../../rt/components/mark-nav/nav-components/nav-share-permission/nav-share-permission.component';
import { MatMenuModule } from '@angular/material/menu';

@Component({
  selector: 'shared-view',
  standalone: true,
  imports: [AvatarComponent, MatTooltipModule, MatCheckboxModule, CommonModule, IconComponent, FormsModule, MatMenuModule, NavSharePermissionComponent],
  templateUrl: './shared-view.component.html',
  styleUrl: './shared-view.component.scss'
})
export class SharedViewComponent {
  @Input() userList: any[];
  @Input() title: string = '';
  @Input() head: string;
  @Input() isSelectAll: boolean = true;
  @Input() canedit: boolean = false;
  @Input() hasshadow: boolean = true;
  @Input() haspadding: boolean = true;
  @Input() hasWrap: boolean = false;
  @Input() wrapavatar: boolean = true;
  @Input() ishorizontal: boolean = false;
  @Input() Info: string;
  @Input() fromFactSheet: boolean = false;
  @Input() isUpdate: boolean = false;
  @Input() mode: string = '';

  @Input() type: string = '';
  @Input() nCaseid: string = null;
  @Input() nId: string = null;
  @Input() nUserid: string;
  @Output() onEvent = new EventEmitter<any>();
  allSelected: boolean = false;

  isSharePermission: boolean = true;

  @Input() viewSelected: boolean = false;
  @Input() creator: string;
  totalUsers: number = 0;

  @Input() enabledEdit:boolean = false; // this will overwrite viewSelected;
  constructor(private individualS: IndividualService, private tost: TostbarService,
    private rolepermit: RolepermitService, private cdr: ChangeDetectorRef) { }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['userList'] && !changes['userList'].firstChange) {
      this.updateTotalUsers()
    }
    if (this.userList) {
      const selectedLength = this.userList.filter(f => f.isSelected).length;
      this.allSelected = (selectedLength || (selectedLength == this.userList.length)) ? true : false;
    }
  }

  ngOnInit() {

    this.updateTotalUsers()
  }

  select(x) {
    if (this.viewSelected && !this.enabledEdit) return;
    x.isSelected = !x.isSelected;
    if (this.userList.filter(f => f.isSelected).length == this.userList.length) {
      this.allSelected = true;
    } else {
      this.allSelected = false;
    }
    this.updateTotalUsers()
    if (this.fromFactSheet) {
      this.onEvent.emit({ type: 'USER-EDIT', data: true });
    }
    if (this.isUpdate) {

      this.updateUesr(x);
      this.onEvent.emit({ type: 'UPDATE-USER-COUNT', data: this.userList.filter(f => f.isSelected).length });
    }
  }

  async updateUesr(x) {
    const mdl = {
      nId: this.nId,
      jUsers: JSON.stringify(this.userList.filter(f => f.isSelected).map(m => m.nUserid)),
      cType: this.type,
      nCaseid: this.nCaseid
    }
    const res = await this.individualS.update_sharelink(mdl);
    if (res) {
      if (x.isSelected) {
        this.tost.openSnackBar((this.type == 'F' ? 'Fact ' : this.type == 'D' ? 'Doc ' : 'Web ') + 'has been shared with select team member', '');
      }
    }
    this.updateTotalUsers()
  }

  selectAllUsers(e) {
    if (this.viewSelected) return;
    if (e.checked) {
      this.userList.forEach(user => {
        user.isSelected = true;
      });
    } else {
      this.userList.forEach(user => {
        user.isSelected = false;
      });
    }
    this.updateUesr(this.userList[0])
    if (this.fromFactSheet) {
      this.onEvent.emit({ type: 'USER-EDIT', data: true });
    }
    this.updateTotalUsers()
  }

  edit() {
    this.onEvent.emit({ type: 'OPEN-EDIT', data: true });
  }

  verifyPermission() {
    this.isSharePermission = this.rolepermit.verifyPermission('SH');
  }


  ngAfterViewInit() {
    this.updateTotalUsers();
  }

  updateTotalUsers() {
    // this.totalUsers = this.userList.filter(a => this.viewSelected ? (a.isSelected) : true)?.length
    this.totalUsers = this.userList.filter(a => (a.isSelected && this.viewSelected) || !this.viewSelected)?.length
    this.cdr.detectChanges();
  }
}
